"""Regenerate mode_vectors.h using independent cipher implementations.

Run with the packages in requirements.txt installed. No AES-dust code is loaded.
The generated fixtures are checked in so ordinary C tests need no Python.
"""
from pathlib import Path

from Cryptodome.Cipher import AES
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


def pattern(length, seed):
    return bytes((seed + 29 * i) & 255 for i in range(length))


def hex_bytes(data):
    return "{" + ",".join(f"0x{x:02x}" for x in data) + "}"


def generate():
    lines = [
        "/* Generated by tests/generate_mode_vectors.py; do not edit by hand.",
        " * Independent references: PyCryptodome AES and cryptography AES-XTS.",
        " * Inputs use byte[i] = (seed + 29*i) & 255 unless stated otherwise.",
        " */",
        "#ifndef AES_DUST_MODE_VECTORS_H",
        "#define AES_DUST_MODE_VECTORS_H",
    ]
    zero = bytes(16)
    for name, variable_key in [("ecb_variable_key", True), ("ecb_variable_plain", False)]:
        lines.append(f"static const uint8_t {name}[128][16] = {{")
        for bit in range(128):
            value = bytearray(16)
            value[bit // 8] = 1 << (bit % 8)
            key, plain = (bytes(value), zero) if variable_key else (zero, bytes(value))
            lines.append("    " + hex_bytes(AES.new(key, AES.MODE_ECB).encrypt(plain)) + ",")
        lines.append("};")
    lines.extend([
        "typedef struct {",
        "    uint32_t len;",
        "    uint8_t key_seed, iv_seed, plain_seed;",
        "    uint8_t crypt[128];",
        "} feedback_vector;",
    ])
    for name, mode in [("cbc", AES.MODE_CBC), ("cfb", AES.MODE_CFB)]:
        lines.append(f"static const feedback_vector {name}_continuation_vectors[] = {{")
        for index, length in enumerate([0, 16, 32, 48, 128]):
            ks, vs, ps = 11 + index, 43 + index, 79 + index
            kwargs = {"segment_size": 128} if mode == AES.MODE_CFB else {}
            cipher = AES.new(pattern(16, ks), mode, iv=pattern(16, vs), **kwargs)
            crypt = cipher.encrypt(pattern(length, ps))
            lines.append(f"    {{{length}, {ks}, {vs}, {ps}, {hex_bytes(crypt or bytes(1))}}},")
        lines.append("};")
    lines.extend([
        "typedef struct {",
        "    uint32_t len;",
        "    uint8_t key_seed, tweak_seed, plain_seed;",
        "    uint8_t crypt[512];",
        "} xts_vector;",
        "static const xts_vector xts_long_vectors[] = {",
    ])
    for index, length in enumerate([16, 32, 48, 512]):
        ks, ts, ps = 13 + index, 61 + index, 113 + index
        encryptor = Cipher(algorithms.AES(pattern(32, ks)), modes.XTS(pattern(16, ts))).encryptor()
        crypt = encryptor.update(pattern(length, ps)) + encryptor.finalize()
        lines.append(f"    {{{length}, {ks}, {ts}, {ps}, {hex_bytes(crypt)}}},")
    lines.extend(["};", "#endif", ""])
    with Path(__file__).with_name("mode_vectors.h").open("w", encoding="ascii", newline="\n") as output:
        output.write("\n".join(lines))


if __name__ == "__main__":
    generate()
